DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC2_GUIDE_MCPVP' OR Tag GLOB 'TXT_KEY_CWC2_GUIDE_MCPVP_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_MCPVP_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_MCPVP_CIV_TEXT_1','McPvP[NEWLINE]Objective warfare, mobility and persistent Server Legacy[NEWLINE]Domination or Culture[NEWLINE][NEWLINE]Choose a mode that matches the map and army, complete one legal objective, and carry the resulting Legacy into later matches. Winning a field battle is useful, but the mode''s explicit objective determines its special payoff.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_MCPVP_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_MCPVP_CIV_TEXT_2','Scout approaches and read the default Hardcore Games timer. Develop a real military and production base before chasing an announced Feast. A rival''s eligible unit can claim it too.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_MCPVP_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_MCPVP_CIV_TEXT_3','Queue the next mode around achievable routes. In CTF, plan both the theft and the safe return; in Sabotage, retain visibility and the required infiltration position. Choose kits and support units for the actual objective instead of only for damage.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_MCPVP_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_MCPVP_CIV_TEXT_4','Use accumulated Legacy and repeated successes to support the chosen victory. Keep a backup plan for a failed objective and protect conventional cities while mobile units are away from the main front.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_MCPVP_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_MCPVP_CIV_TEXT_5','- Mode choice creates different tactical routes to lasting rewards.[NEWLINE]- Kits and objective actions give mobile units several useful jobs.[NEWLINE]- Legacy persists beyond one match rather than resetting the entire campaign.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_MCPVP_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_MCPVP_CIV_TEXT_6','- Objectives have specific visibility, position, movement and timing restrictions.[NEWLINE]- Flag carriers cannot attack and are easier to punish on the return route.[NEWLINE]- Infiltration can be interrupted and a Feast is contested rather than reserved for McPvP.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_MCPVP_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_MCPVP_CIV_TEXT_7','- Defend likely flag return routes as well as the city where a flag was stolen.[NEWLINE]- Remove or force away a revealed infiltrator before the timer completes.[NEWLINE]- Contest the Feast only when the terrain and army make it a good fight.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_MCPVP_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_MCPVP_CIV_TEXT_8','- Changing the queued mode and expecting the current match to restart.[NEWLINE]- Stealing a flag without a safe legal return route.[NEWLINE]- Treating an announced Feast as an automatic reward or a partial infiltration as a completed objective.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_MCPVP_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_MCPVP_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Sol Intellect: A successful infiltration can disrupt a productive builder while forcing defense around valuable construction cities.[NEWLINE][NEWLINE]RomanGladius Network: Mobile pressure on large economic cities can tax staffing money and exploit a defense spread among several Servers.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]The Last City: A concentrated defended approach makes unobserved city objectives and safe return routes harder to obtain.[NEWLINE][NEWLINE]The Threshold Court: A working House network can place a defender near a distant objective before a travelling raider expects reinforcement.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_MCPVP_DESCRIPTION','McPvP');
