INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_MCPVP_BACKGROUND','Choose a mode that matches the map and army, complete one legal objective, and carry the resulting Legacy into later matches. Winning a field battle is useful, but the mode''s explicit objective determines its special payoff.');
