INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_MCPVP_LEADER_BACKGROUND','Choose a mode that matches the map and army, complete one legal objective, and carry the resulting Legacy into later matches. Winning a field battle is useful, but the mode''s explicit objective determines its special payoff.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) SELECT 'TXT_KEY_CWC2_GUIDE_MCPVP_LEADER_BACKGROUND',Text FROM Language_en_US WHERE Tag='TXT_KEY_MCPVP_LEADER_PEDIA';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_MCPVP_STRATEGY','Choose a mode that matches the map and army, complete one legal objective, and carry the resulting Legacy into later matches. Winning a field battle is useful, but the mode''s explicit objective determines its special payoff.[NEWLINE][NEWLINE]Scout approaches and read the default Hardcore Games timer. Develop a real military and production base before chasing an announced Feast. A rival''s eligible unit can claim it too.[NEWLINE][NEWLINE]Queue the next mode around achievable routes. In CTF, plan both the theft and the safe return; in Sabotage, retain visibility and the required infiltration position. Choose kits and support units for the actual objective instead of only for damage.[NEWLINE][NEWLINE]Use accumulated Legacy and repeated successes to support the chosen victory. Keep a backup plan for a failed objective and protect conventional cities while mobile units are away from the main front.');
