INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_MCPVP_LEADER_TEXT_2','Scout approaches and read the default Hardcore Games timer. Develop a real military and production base before chasing an announced Feast. A rival''s eligible unit can claim it too.[NEWLINE][NEWLINE]Queue the next mode around achievable routes. In CTF, plan both the theft and the safe return; in Sabotage, retain visibility and the required infiltration position. Choose kits and support units for the actual objective instead of only for damage.[NEWLINE][NEWLINE]Use accumulated Legacy and repeated successes to support the chosen victory. Keep a backup plan for a failed objective and protect conventional cities while mobile units are away from the main front.');
