INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_MCPVP_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Sol Intellect: A successful infiltration can disrupt a productive builder while forcing defense around valuable construction cities.[NEWLINE][NEWLINE]RomanGladius Network: Mobile pressure on large economic cities can tax staffing money and exploit a defense spread among several Servers.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]The Last City: A concentrated defended approach makes unobserved city objectives and safe return routes harder to obtain.[NEWLINE][NEWLINE]The Threshold Court: A working House network can place a defender near a distant objective before a travelling raider expects reinforcement.');
